import XCTest
import KSLCore
import KSLPhysics
@testable import KSLGuidance

final class TouchdownBounceOwnershipTests: XCTestCase {
  func testRecordedBounceKeepsFinalOwnership() throws {
    let c = try JSONDecoder().decode(MissionConfiguration.self, from: Data(Self.configuration.utf8))
    let states = try JSONDecoder().decode([VehicleState].self, from: Data(Self.states.utf8))
    let atmosphere = try AtmosphericModelEngine(planet: c.planet)
    let aero = try AerodynamicsEngine(referenceArea: c.vehicle.referenceArea)
    let mission = LandingMissionController(configuration: c, atmosphere: atmosphere,
      aerodynamics: aero, externalPlanning: true, initialPhase: .flare)
    _ = try mission.update(states[0])
    XCTAssertEqual(try mission.update(states[1]).phase, .touchdown)
    let bounce = try mission.update(states[2])
    XCTAssertEqual(bounce.phase, .flare)
    XCTAssertNil(bounce.entry)
    XCTAssertFalse(bounce.violations.contains { $0.message.contains("terminal path") || $0.message.contains("MM305") })
  }
